#include <type_traits>

static int fails { 0 };
#define CHECK(cond) do { if (!(cond)) { std::cerr << "FAIL: " #cond " @line " << __LINE__ << "\n"; ++fails; } } while(0)

int main()
{
    // scale(2, 1.5): int * double should produce double 3.0, not int 3
    auto result = scale(2, 1.5);
    CHECK(result == 3.0);
    CHECK(std::is_floating_point_v<decltype(result)>);

    // scale(4, 2): int * int = int 8
    auto result2 = scale(4, 2);
    CHECK(result2 == 8);

    if (!fails)
        std::cout << "PASS\n";
    return fails ? 1 : 0;
}

