#include <string>

// describe() should return a human-readable tag for its argument.
// Bug: there is no describe(bool) overload. When describe(true) is called,
// overload resolution promotes bool to int (rung 2 of the matching ladder)
// and selects describe(int), returning "int:1" instead of "bool:true".
// Fix: add a describe(bool) overload that returns "bool:true" or "bool:false".

inline std::string describe(int x)
{
    return "int:" + std::to_string(x);
}

inline std::string describe(double x)
{
    return "double:" + std::to_string(x);
}

