drills.solution:
#include <string>

inline std::string describe(int x)
{
    return "int:" + std::to_string(x);
}

inline std::string describe(double x)
{
    return "double:" + std::to_string(x);
}

inline std::string describe(bool x)
{
    return x ? "bool:true" : "bool:false";
}
